9	/* ── section shell ────────────────────────────────────────────────────────
10	   Every band on the wizard is the same object: a number, a title, a line of
11	   help, and a body that dims until the sections before it are answered. */
12	export function Band({
13	  n, id, title, help, live, done, aside, children,
14	}: {
15	  n: number; id: string; title: string; help: string;
16	  live: boolean; done?: boolean; aside?: React.ReactNode; children: React.ReactNode;
17	}) {
18	  return (
19	    <section id={id} aria-labelledby={`${id}-h`}
20	             className={"transition-opacity duration-300 " +
21	                        (live ? "opacity-100" : "pointer-events-none select-none opacity-35")}>
22	      <div className="flex flex-wrap items-center justify-between gap-x-5 gap-y-2.5">
23	        <div className="flex min-w-0 flex-col gap-1">
24	          <div className="flex items-center gap-3">
25	            <span className={"grid h-7 w-7 flex-none place-items-center rounded-full text-[12.5px] font-extrabold " +
26	              (done ? "bg-[linear-gradient(100deg,#0f9169,#11c88e)] text-[#01201a]"
27	                    : live ? "bg-[#fff] text-[#0a1f52]"
28	                           : "border border-rim-hi bg-surface text-tx-faint")}>
29	              {/* tone="inherit": the icon otherwise forces its own mint-green
30	                  class regardless of context, which on this cyan/green gradient
31	                  reads as a green tick on a green disc — unreadable in both
32	                  themes. Inheriting lets the dark ink colour set above win. */}
33	              {done ? <Icon name="checkcircle" size={14} tone="inherit" /> : n}
34	            </span>
35	            <h2 id={`${id}-h`} className="text-[19px] font-extrabold tracking-[-0.028em] text-white">{title}</h2>
36	          </div>
37	          <p className="text-[12.8px] text-tx-mute sm:pl-10">{help}</p>
38	        </div>
39	        {/* the control can be wider than a phone, so it gets its own full row
40	            there and scrolls inside it rather than off the viewport */}
41	        {aside && <div className="w-full min-w-0 sm:w-auto sm:max-w-[60%]">{aside}</div>}
42	      </div>
43	      <div className="mt-4 sm:pl-10">{children}</div>
44	    </section>
45	  );
46	}
