48	/* ── one selectable tile ──────────────────────────────────────────────── */
49	export function Pick({
50	  on, onClick, className = "", children, ...rest
51	}: React.ButtonHTMLAttributes<HTMLButtonElement> & { on: boolean }) {
52	  return (
53	    <button type="button" onClick={onClick} aria-pressed={on}
54	            className={"card card-i text-left " + (on ? "card-on " : "") + className} {...rest}>
55	      {children}
56	    </button>
57	  );
58	}
59	
60	/* ── plan card ────────────────────────────────────────────────────────── */
61	/* The card PRINTS a price, it does not work one out.
62	   `effectiveMonthlyCents` arrives already discounted for the selected term, from
63	   the same basis the charge path uses. The sandbox version multiplied a rate by
64	   a term discount right here, which is a second pricing formula — and the moment
65	   it disagrees with `orderQuote` the customer sees one number and is charged
66	   another. */
67	export function PlanCard({ p, blurb, on, onClick }: {
68	  p: PlanOption; blurb?: string; on: boolean; onClick: () => void;
69	}) {
70	  const eff = p.effectiveMonthlyCents;
71	  const discounted = p.effectiveMonthlyCents < p.monthlyCents;
72	  return (
73	    <Pick on={on} onClick={onClick} className="relative flex flex-col gap-3 p-3.5">
74	      {p.recommended && (
75	        <span className="absolute -top-[9px] left-3.5 rounded-full bg-[linear-gradient(100deg,#1a55cf,#6f2ee0)]
76	                         px-2.5 py-[3px] text-[10px] font-extrabold uppercase tracking-[0.07em] text-white
77	                         shadow-[0_0_13px_-8px_rgba(88,60,255,0.5)]">
78	          Most popular
79	        </span>
80	      )}
81	      <span className="flex flex-col gap-0.5">
82	        <span className="text-[15px] font-extrabold tracking-[-0.02em] text-white">{p.name}</span>
83	        {/* Who it is FOR. The specs are already listed below, so repeating them
84	            here spent the one line that could say something else. */}
85	        <span className="text-[11.5px] text-tx-faint">{blurb ?? `${p.cpuCores} vCPU · ${p.ramMB / 1024} GB RAM`}</span>
86	      </span>
87	
88	      <span className="flex items-baseline gap-1.5">
89	        <span className="num bg-[linear-gradient(96deg,#3fbcd8,#8fb0e8)] bg-clip-text text-[25px] text-transparent">
90	          {money(eff)}
91	        </span>
92	        <span className="text-[11.5px] text-tx-dim">/mo</span>
93	      </span>
94	      {discounted && (
95	        <span className="-mt-2 text-[11px] text-tx-faint">
96	          {money(p.monthlyCents)}/mo billed monthly
97	        </span>
98	      )}
99	      {/* An intro rate is stated WITH its renewal rate or not at all — a first-term
100	          price shown alone reads as the forever price. */}
101	      {p.introMonthlyCents !== null && p.introRenewalMonthlyCents !== null && (
102	        <span className="-mt-2 text-[11px] text-amber">
103	          {money(p.introMonthlyCents)}/mo first term, then {money(p.introRenewalMonthlyCents)}/mo
104	        </span>
105	      )}
106	
107	      <ul className="flex flex-col gap-1.5">
108	        {[
109	          { icon: "cpu", text: `${p.cpuCores} vCPU` },
110	          { icon: "ram", text: `${p.ramMB / 1024} GB RAM` },
111	          { icon: "database", text: `${p.diskGB} GB NVMe` },
112	          { icon: "nodes", text: `${p.bandwidthTB} TB transfer` },
113	        ].map((sp) => (
114	          <li key={sp.text} className="flex items-center gap-2 text-[12px] text-tx-body">
115	            <Icon name={sp.icon} size={14} className="flex-none opacity-85" />{sp.text}
116	          </li>
117	        ))}
118	      </ul>
119	      <span className={"btn-ghost mt-auto h-[36px] w-full rounded-[9px] text-[12.5px] " +
120	                       (on ? "border-transparent bg-[linear-gradient(100deg,#1a55cf,#6f2ee0)] text-white" : "")}>
121	        {on ? "Selected" : "Select plan"}
122	      </span>
123	    </Pick>
124	  );
125	}
126	
127	/* ── region card ──────────────────────────────────────────────────────── */
128	/* The sandbox card carried a site count and a latency figure per region. The
129	   platform records neither, so rather than print invented numbers the card shows
130	   what is true: where it is, and which continent it sits on. */
131	export function RegionCard({ r, on, onClick }: {
132	  r: { key: string; name: string; area: string; flag: string; ms?: number; rec?: boolean };
133	  on: boolean; onClick: () => void;
134	}) {
135	  return (
136	    <Pick on={on} onClick={onClick} className="card-glass flex items-center gap-3 p-3"
137	          style={{ "--tone": "#3fd0ff" } as React.CSSProperties}>
138	      <Flag code={r.flag} size={26} />
139	      <span className="flex min-w-0 flex-1 flex-col gap-0.5">
140	        <span className="flex items-center gap-2">
141	          <span className="trunc text-[13.5px] font-bold text-white">{r.name}</span>
142	          {r.rec && (
143	            <span className="flex-none rounded-full border border-[rgba(72,148,255,0.4)] bg-[rgba(10,40,96,0.6)]
144	                             px-2 py-[1px] text-[9.5px] font-bold text-[#8dbde8]">
145	              Recommended
146	            </span>
147	          )}
148	        </span>
149	        <span className="trunc text-[11.5px] text-tx-faint">{r.area}</span>
150	      </span>
151	      {/* "~" because this is the region's nominal round-trip, not a measurement
152	          of THIS visitor's connection — nothing probes that. */}
153	      {r.ms !== undefined && (
154	        <span className="flex flex-none items-center gap-1.5 text-[11.5px] font-semibold text-mint">
155	          <Bars ms={r.ms} />~{r.ms} ms
156	        </span>
157	      )}
158	    </Pick>
159	  );
160	}
161	
162	/** Three bars, filled by how good the latency is — a glanceable read that a
163	    bare number does not give. */
164	function Bars({ ms }: { ms: number }) {
165	  const lit = ms < 40 ? 3 : ms < 70 ? 2 : 1;
166	  return (
167	    <span className="flex items-end gap-[2px]" aria-hidden>
168	      {[5, 8, 11].map((h, i) => (
169	        <span key={h} style={{ height: h }}
170	              className={"w-[3px] rounded-[1px] " + (i < lit ? "bg-mint" : "bg-[rgba(120,160,210,0.28)]")} />
171	      ))}
172	    </span>
173	  );
174	}
