176	/* ── add-on row ───────────────────────────────────────────────────────── */
177	export function AddonRow({ a, on, onClick }: {
178	  a: { key: string; name: string; note: string; monthlyCents: number; icon: string; free: boolean };
179	  on: boolean; onClick: () => void;
180	}) {
181	  return (
182	    <Pick on={on} onClick={onClick} className="flex items-center gap-3 p-3">
