185	        (on ? "border-transparent bg-[linear-gradient(100deg,#1a55cf,#6f2ee0)] text-[#fff]" : "border-rim-hi bg-well")}>
186	        {/* `check` — a bare tick, not `checkcircle`: that one draws its OWN
187	            ring, and a circle inscribed in this rounded-SQUARE box leaves
188	            visibly more gap at the corners than the edges, reading as the
189	            checkmark sitting off-center. */}
190	        {on && <Icon name="check" size={11} tone="inherit" />}
191	      </span>
192	      <Plate name={a.icon} size={22} />
193	      <span className="flex min-w-0 flex-1 flex-col gap-0.5">
194	        <span className="trunc text-[13px] font-bold text-white">{a.name}</span>
195	        <span className="trunc text-[11.3px] text-tx-faint">{a.note}</span>
196	      </span>
197	      <span className="flex-none text-right">
198	        <span className={"block text-[12.5px] font-bold " + (a.free ? "text-mint" : "text-white")}>
199	          {a.free ? "Included" : money(a.monthlyCents) + "/mo"}
200	        </span>
201	      </span>
202	    </Pick>
203	  );
204	}
