206	/* ── the service mark ───────────────────────────────────────────────────
207	   One rendered neon icon per service, carried everywhere the service is
208	   named — the picker, the summary, the receipt — so it reads as the same
209	   object throughout. */
210	export function SvcIcon({ name, size = 64, className = "" }: {
211	  name: string; size?: number; className?: string;
