221	/* ── the step marks above the wizard ────────────────────────────────────
222	   Floating, no panel behind them: done is a filled mint disc with a tick,
223	   the current step is a filled brand disc with a ring, the rest are hollow.
224	   The connector fills as you advance. */
225	export function StepMarks({ steps, i, go }: {
226	  steps: { key: string; label: string; done: boolean; live: boolean }[];
227	  i: number; go: (n: number) => void;
228	}) {
229	  return (
230	    <ol className="noscroll mx-auto flex w-full max-w-[720px] items-start justify-center gap-0 overflow-x-auto px-2">
231	      {steps.map((s, n) => {
232	        const cur = n === i, past = n < i;
233	        return (
234	          <li key={s.key} className="flex flex-none items-start">
235	            <button onClick={() => s.live && go(n)} disabled={!s.live}
236	                    aria-current={cur ? "step" : undefined}
237	                    className="group flex w-[104px] flex-col items-center gap-2 disabled:cursor-default">
238	              <span className={"grid h-[30px] w-[30px] place-items-center rounded-full text-[12.5px] font-extrabold transition-all duration-300 " +
239	                (past ? "bg-[linear-gradient(135deg,#14c5e4,#11c88e)] text-[#012019]"
240	                      : cur ? "bg-[linear-gradient(135deg,#2f7eef,#6f2ee0)] text-[#fff] ring-[3px] ring-[rgba(111,46,224,0.28)]"
241	                            : "border border-rim-hi text-tx-faint")}>
242	                {/* tone="inherit" — see the same fix in Band above. */}
243	                {past ? <Icon name="checkcircle" size={14} tone="inherit" /> : n + 1}
244	              </span>
245	              <span className={"whitespace-nowrap text-[11.5px] font-bold transition-colors " +
246	                (cur ? "text-white" : past ? "text-tx-body" : "text-tx-faint")}>{s.label}</span>
247	            </button>
248	            {n < steps.length - 1 && (
249	              <span aria-hidden
250	                    className={"mt-[15px] h-px w-8 flex-none transition-colors duration-300 " +
251	                      (past ? "bg-[linear-gradient(90deg,#14c5e4,#11c88e)]" : "bg-rim-hi")} />
252	            )}
253	          </li>
254	        );
255	      })}
256	    </ol>
257	  );
258	}
