260	/* ── a line of the order, with its own mark ─────────────────────────────── */
261	export function Spec({ icon, children, flag }: {
262	  icon?: string; children: React.ReactNode; flag?: string;
263	}) {
264	  return (
265	    <li className="flex items-center gap-2 text-[12px] text-tx-body">
266	      {flag ? <Flag code={flag} size={15} /> : <Icon name={icon ?? "checkcircle"} size={14} className="flex-none opacity-85" />}
267	      {children}
