272	/* ── extra storage ──────────────────────────────────────────────────────
273	   Metered, not a checkbox: it is priced per GB and cannot be shrunk after
274	   deploy, so the size and its cost move together under the customer's hand. */
275	export function DiskMeter({ gb, perGbCents, onChange }: {
276	  gb: number;
277	  /* The per-GB rate is the SERVER's (`extraDiskPerGbCents`), the same function
278	     the charge path reads — not a constant kept alongside the slider. */
279	  perGbCents: number;
280	  onChange: (n: number) => void;
281	}) {
282	  const pct = (gb / DISK_STEP.max) * 100;
283	  return (
284	    <div className="card flex flex-col gap-3 p-3.5">
285	      <div className="flex items-center gap-3">
286	        <img src="/nx/svc/volume.webp" alt="" aria-hidden draggable={false}
287	             className="h-[42px] w-[42px] flex-none object-contain" />
288	        <span className="flex min-w-0 flex-1 flex-col gap-0.5">
289	          <span className="text-[13px] font-bold text-white">Extra storage</span>
290	          <span className="text-[11.3px] text-tx-faint">
291	            {money(perGbCents)}/GB per month · cannot be shrunk later
292	          </span>
293	        </span>
294	        <span className="flex-none text-right">
295	          <span className="block text-[13px] font-extrabold text-white">
296	            {gb === 0 ? "None" : `+${gb} GB`}
297	          </span>
298	          <span className="block text-[10.5px] text-tx-faint">
299	            {gb === 0 ? "included only" : money(gb * perGbCents) + "/mo"}
300	          </span>
301	        </span>
302	      </div>
303	
304	      <div className="flex items-center gap-3">
305	        <input type="range" aria-label="Extra storage in GB"
306	               min={DISK_STEP.min} max={DISK_STEP.max} step={DISK_STEP.step} value={gb}
307	               onChange={(e) => onChange(+e.target.value)}
308	               className="range flex-1"
309	               style={{ "--pct": `${pct}%` } as React.CSSProperties} />
310	        <div className="flex flex-none gap-1.5">
311	          {[0, 50, 100, 250].map((v) => (
312	            <button key={v} onClick={() => onChange(v)}
313	                    className={"rounded-full px-2.5 py-1 text-[11px] font-bold transition-colors " +
314	                      (gb === v ? "bg-[linear-gradient(100deg,#1a55cf,#6f2ee0)] text-white"
315	                                : "border border-rim-hi text-tx-dim hover:text-white")}>
316	              {v === 0 ? "None" : `${v}G`}
317	            </button>
318	          ))}
319	        </div>
320	      </div>
321	    </div>
322	  );
323	}
324	
325	/* ── a section that starts folded ───────────────────────────────────────
326	   Settings and add-ons already carry working defaults, so they open closed:
327	   the customer opens them only if they want something other than the
328	   recommendation. */
329	/* `open` is CONTROLLED when a parent passes it. The two folds on the configure
330	   step sit side by side, so opening one and leaving the other shut left a tall
331	   empty column next to the expanded panel — they open and close together. */
332	export function Fold({ title, sub, icon, children, badge, open: openProp, onToggle }: {
333	  title: string; sub: string; icon: string; badge?: string;
334	  children: React.ReactNode; open?: boolean; onToggle?: (open: boolean) => void;
335	}) {
336	  const [ownOpen, setOwnOpen] = useState(false);
337	  const open = openProp ?? ownOpen;
338	  const flip = () => { const v = !open; setOwnOpen(v); onToggle?.(v); };
339	  return (
340	    <div className="card overflow-hidden p-0">
341	      <button onClick={flip} aria-expanded={open}
342	              className="flex w-full items-center gap-3 p-3.5 text-left">
343	        <Plate name={icon} size={22} />
344	        <span className="flex min-w-0 flex-1 flex-col gap-0.5">
345	          <span className="flex items-center gap-2">
346	            <span className="text-[13.5px] font-bold text-white">{title}</span>
347	            {badge && (
348	              <span className="rounded-full border border-[rgba(72,148,255,0.35)] bg-[rgba(10,40,96,0.5)]
349	                               px-2 py-[1px] text-[10px] font-bold text-[#8dbde8]">{badge}</span>
350	            )}
351	          </span>
352	          <span className="trunc text-[11.5px] text-tx-faint">{sub}</span>
