/* The shapes the deploy wizard renders.
 *
 * Every money field below is CENTS, ALREADY COMPUTED BY THE SERVER. The wizard
 * never multiplies, discounts or prorates — it prints. That is the whole point
 * of these types: they make it impossible for a component to be handed a raw
 * rate and be tempted to do the arithmetic itself, which is how a display price
 * and a charged price drift apart.
 *
 * If a screen needs a number that isn't here, add it to the server page and
 * pass it down — do not compute it in a component.
 */

import type { ConfigField } from "@/lib/game-config";

export type PlanOption = {
  id: string;
  slug: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  /** Regular monthly rate, for the struck-through "was" figure. */
  monthlyCents: number;
  /**
   * Effective monthly rate at the CURRENTLY SELECTED term, computed server-side
   * from the same annual-discount basis the charge path uses. Recomputed by the
   * server when the term changes — never derived here.
   */
  effectiveMonthlyCents: number;
  /** Set when the plan carries an intro rate, so the copy can be honest. */
  introMonthlyCents: number | null;
  introRenewalMonthlyCents: number | null;
  recommended?: boolean;
};

export type OsOption = {
  id: string;
  name: string;
  version: string;
  /** Icon key in the interface sprite sheet. */
  icon: string;
  /** Which tab it belongs under in the Server settings panel. */
  category: "PLAIN_OS" | "CONTROL_PANEL" | "APPLICATION";
  /**
   * `ubuntu` | `debian` | `almalinux` | `rocky` | ... — the platform's own
   * grouping key. Each OsTemplate row is ONE VERSION; the design shows a card
   * per family with its versions as chips underneath, which is exactly what
   * this field already expresses.
   */
  family: string;
  /**
   * Key into the third-party mark sheet, when one exists. Control panels and
   * applications have their own drawn marks; the interface icon set has no
   * cPanel or WordPress glyph, so without this every one of them renders as the
   * same generic cube. Null for plain OS, which uses the interface set.
   */
  spriteKey: string | null;
};

export type TermOption = {
  months: number;
  label: string;
  /** Discount percent applied at this term, server-supplied. */
  discountPercent: number;
};

export type AddonOption = {
  key: "backup" | "malware" | "docker" | "ip";
  name: string;
  note: string;
  icon: string;
  /** Zero means genuinely included, not "price unknown". */
  monthlyCents: number;
  free: boolean;
};

/** What the sticky cart shows. Comes straight from `quoteOrder`. */
export type CartPrice = {
  totalCents: number;
  months: number;
  regularPlanCents: number;
  promoName: string;
  promoCreditCents: number;
  couponLabel: string | null;
  couponDiscountCents: number;
  couponError: string | null;
  introRenewalMonthly: number | null;
  /** What this order actually renews at, every cycle — plan plus every
   *  recurring add-on at full price. See lib/order.ts's renewalTotalCents. */
  renewalTotalCents: number;
} | null;


/* ── game ─────────────────────────────────────────────────────────────────
   A family is what the customer picks; a TIER is what they buy. Each GamePlan
   row is one tier of one family, so the picker is two levels and the money only
   attaches at the second. */

export type GameTier = {
  id: string;
  name: string;
  ramMB: number;
  cpuCores: number;
  diskGB: number;
  /** Player slots, when the family has a meaningful cap. */
  slots: number | null;
  /** Server-computed, per term — the wizard never derives it. */
  monthlyCents: number;
  termMonths: number;
};

export type GameFamilyOption = {
  family: string;
  name: string;
  /** Artwork path, or null when the family has none (card falls back). */
  art: string | null;
  /** Loader / flavour options, from the platform's own family schema. */
  variants: { id: string; label: string; description?: string }[];
  defaultVariant: string;
  tiers: GameTier[];
  /** Cheapest tier, for the "from" line on the family card. */
  fromCents: number;
  /** Genre tags from the platform catalog, for the picker's filter chips. */
  genres: string[];
  /** Minecraft alone needs a play subdomain before it can be ordered. */
  needsSubdomain: boolean;
  /**
   * This family's full config schema (lib/game-config.ts) — every field, not
   * just the required ones. The wizard shows `required` fields inline and
   * folds the rest under a collapsed "Advanced settings" section, since a
   * non-required field always has a sensible default and is equally
   * editable later from the dashboard's Settings tab. Empty for a family
   * with no customization schema at all.
   */
  checkoutFields: ConfigField[];
  /** Leads the grid, badged "Popular" — a short, owner-picked list, not a
   *  computed ranking (there's no real play-count/order-volume signal to
   *  rank by yet). */
  popular: boolean;
};

/* ── hosting & email ──────────────────────────────────────────────────────
   Both are bought against a DOMAIN rather than a machine, which is why neither
   carries a region: the customer picks capacity and a name, not a location. */

export type HostingPlanOption = {
  id: string;
  name: string;
  tagline: string;
  diskGB: number;
  maxSites: number;
  maxDatabases: number;
  bandwidthTB: number;
  mailboxes: number;
  freeMigration: boolean;
  featured: boolean;
  monthlyCents: number;
};

export type EmailPlanOption = {
  id: string;
  name: string;
  /** Included mailboxes. */
  mailboxes: number;
  /** Storage PER mailbox. */
  storageGB: number;
  monthlyCents: number;
  termMonths: number;
};

