import { chromium } from "playwright";

const BASE = "http://51.79.162.96:8080";
const EMAIL = "admin@nxeon.local";
const PASSWORD = "I7eTwwinDLjbPD57";
const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad";

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1400, height: 1000 } });

page.on("console", (msg) => {
  if (msg.type() === "error") console.log("[console.error]", msg.text());
});
page.on("pageerror", (err) => console.log("[pageerror]", err.message));

async function shot(name) {
  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: true });
  console.log("saved", name);
}

console.log("Logging in...");
await page.goto(`${BASE}/login`, { waitUntil: "networkidle" });
await page.fill('input[name="email"]', EMAIL);
await page.fill('input[name="password"]', PASSWORD);
await Promise.all([
  page.waitForNavigation({ waitUntil: "networkidle" }).catch(() => {}),
  page.click('button[type="submit"]'),
]);
console.log("post-login url:", page.url());

console.log("Going to deploy wizard...");
await page.goto(`${BASE}/dashboard/deploy`, { waitUntil: "networkidle" });
await page.waitForTimeout(1500);
console.log("deploy url:", page.url());

// pick VPS service tile if a service-choice screen shows
const vpsTile = page.locator('text=/^VPS Servers$/').first();
if (await vpsTile.count()) {
  console.log("Clicking VPS tile...");
  await vpsTile.click();
  await page.waitForTimeout(800);
}

await shot("01-vps-plan-cards-monthly");

// Try to switch to Annual term
const annualChip = page.locator('button:has-text("Annual")').first();
if (await annualChip.count()) {
  await annualChip.click();
  await page.waitForTimeout(600);
  await shot("02-vps-plan-cards-annual");
} else {
  console.log("No Annual chip found on this step");
}

// Select the Standard plan (2nd card) to advance to region step
const cards = page.locator('button:has-text("Select plan")');
const count = await cards.count();
console.log("plan cards found:", count);
if (count >= 2) {
  await cards.nth(1).click();
  await page.waitForTimeout(800);
}

// Walk forward via "Next"/"Continue" buttons a few times to reach payment/order-summary
for (let i = 0; i < 6; i++) {
  const next = page.locator('button:has-text("Next"), button:has-text("Continue")').first();
  if (await next.count()) {
    const disabled = await next.isDisabled().catch(() => false);
    if (disabled) break;
    await next.click();
    await page.waitForTimeout(600);
  } else break;
}
await shot("03-vps-order-summary-annual");

await browser.close();
console.log("DONE");

